{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "Welcome to the Grinder",
          "intent": "Establish the protagonist's arrival in a lethal tutorial and their discovery of the broken arena geometry.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist reaches the threshold of the final tutorial boss arena."
        },
        {
          "section_id": 2,
          "title": "The Clipping Point",
          "intent": "Depict the combat encounter where the protagonist exploits a corner seam to avoid damage and kill the boss.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The tutorial boss dies from falling through the world geometry."
        },
        {
          "section_id": 3,
          "title": "Looting the Void",
          "intent": "Show the protagonist gathering high-level drops from the glitched kill and finding the exit.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The protagonist steps through the exit portal into the main world."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "Statistical Anomalies",
          "intent": "The protagonist analyzes their broken rewards and decides to dump all points into Luck.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The protagonist confirms the final stat point allocation into Luck."
        },
        {
          "section_id": 2,
          "title": "The Long Walk to Town",
          "intent": "Demonstrate the immediate effects of high Luck during a dangerous journey to the first settlement.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The protagonist arrives at the gates of the starting town, Oakhaven."
        },
        {
          "section_id": 3,
          "title": "Blending In (Poorly)",
          "intent": "Establish a temporary identity and find a place to lay low while avoiding system-enforced 'corrections'.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "The protagonist secures a room at a local inn under a false name."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "Casing the Joint",
          "intent": "Identify the Merchant Guild's vault and the physical flaws in its magical security.",
          "section_role": "investigation",
          "target_scene_count": 4,
          "end_condition": "The protagonist identifies a specific wall segment with a rendering error."
        },
        {
          "section_id": 2,
          "title": "The Heist of the Century",
          "intent": "Use high crit-rate to 'damage' the physics of the vault door and slip inside.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The protagonist successfully bypasses the vault door and enters the treasure room."
        },
        {
          "section_id": 3,
          "title": "The Ghost of the Vault",
          "intent": "Loot the vault and trigger an alarm that forces a frantic, luck-based escape.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The protagonist escapes the city walls as the Merchant Guild declares a bounty."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Hounds are Loose",
          "intent": "Show the protagonist being tracked by elite enforcers and fleeing toward a high-level zone.",
          "section_role": "pressure",
          "target_scene_count": 3,
          "end_condition": "The protagonist enters the boundaries of the 'Screaming Peaks' monster den."
        },
        {
          "section_id": 2,
          "title": "Aggro Swap",
          "intent": "Use movement exploits to transfer the aggression of high-level mobs onto the pursuing hunters.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The hunters are pinned down by a swarm of elite monsters."
        },
        {
          "section_id": 3,
          "title": "Predator Becomes Prey",
          "intent": "The protagonist realizes they can use the chaos to take out the hunters and the zone boss.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "The protagonist spots the regional World Boss sleeping nearby."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Perfect Bait",
          "intent": "Lure the World Boss toward a specific cliff edge known for fall-damage bugs.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "The World Boss is positioned exactly at the edge of the Peak of Despair."
        },
        {
          "section_id": 2,
          "title": "Newton's Third Law (Broken)",
          "intent": "Use a low-level knockback skill to trigger a massive fall-damage calculation error.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The World Boss hits the ground, triggering an overflow damage number."
        },
        {
          "section_id": 3,
          "title": "The Global Ping",
          "intent": "The System reacts to the impossible kill with a world-wide announcement, blowing the protagonist's cover.",
          "section_role": "resolution",
          "target_scene_count": 3,
          "end_condition": "The global system announcement text fades from the sky."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The System's Chosen",
          "intent": "The Hero party arrives to 'fix' the glitch, forcing the protagonist into a high-stakes confrontation.",
          "section_role": "pressure",
          "target_scene_count": 4,
          "end_condition": "The Hero party initiates combat with the protagonist."
        },
        {
          "section_id": 2,
          "title": "PvP (Player vs Patch)",
          "intent": "The protagonist uses unconventional tactics to survive against the 'legitimate' heroes.",
          "section_role": "rising_action",
          "target_scene_count": 4,
          "end_condition": "The protagonist disables the Hero party's leader with a status-effect loop."
        },
        {
          "section_id": 3,
          "title": "Race to the Border",
          "intent": "The protagonist flees toward the Unpatched zone as the server maintenance countdown begins.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The protagonist reaches the shimmering barrier of the Beta-Test region."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "Breaking the Fourth Wall",
          "intent": "Force a way through the system barrier using every exploit gathered so far.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "The barrier shatters, allowing entry into the Outlands."
        },
        {
          "section_id": 2,
          "title": "The Fog of the Beta",
          "intent": "A final chase through a region where the laws of physics are actively fluctuating.",
          "section_role": "rising_action",
          "target_scene_count": 3,
          "end_condition": "The Hero party loses the protagonist's trail in the chaotic terrain."
        },
        {
          "section_id": 3,
          "title": "Beyond the Patch",
          "intent": "The protagonist finds safety in the lawless zone and prepares for a life outside the System's control.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "The protagonist looks out over the unmapped territories as the server maintenance completes."
        }
      ]
    }
  ]
}

